#' Synthetic outcome tests with HC, BCH, IM and SCPC inference.
#'
#'@description
#' `synth()` runs synthetic outcome tests on regressions with HC inference, BCH
#' and IM inference using increasing numbers of clusters, and SCPC inference
#' using increasing values of the average correlation bound `avc`,
#' to test the null hypothesis that
#' the dependent variable is generated by a quadratic in longitude and latitude
#' plus noise and is therefore independent of the explanatory variable.
#'
#' @inheritParams placebo
#' @param nSim The number of synthetic outcomes to generate. Defaults to 1000
#'   but lower values should be used first to get an idea of how the regression
#'   is behaving.
#' @param max_clus The maximum number of large clusters to examine, for BCH and
#'   IM. Defaults to 6.
#' @param xy_interaction Add the product of longitude and latitude to the
#'   quadratic trend in them that generates the synthetic outcome. Defaults to
#'   `FALSE`, where the trend is a quadratic in each separately.
#' @details See [placebo()] for the inference methods.
#' @return A list containing Results which summarizes the synthetic outcome
#'   p values, with the same rows as [placebo()], and
#'   Spatial_Params giving the Moran test value and the range and structure used
#'   to generate the synthetic outcomes. Show the results with [synth_table()].
#' @export
#'
#' @examples
#' library(spatInfer)
#' data(opportunity)
#' # Use 100 observations and 100 simulations to speed things up. Turn off parallel processing.
#' set.seed(123)
#' opportunity=opportunity |> dplyr::slice_sample(n=100)
#' # Use the number of splines and PCs indicated by optimal_basis()
#' syn=synth(mobility~single_mothers+short_commute+gini+dropout_rate+social_cap,
#' opportunity,
#' splines=6,
#' pc_num=15,
#' nSim=100,
#' Parallel=FALSE,
#' max_clus = 7,
#' avc=c(0.02,0.04,0.06)
#' )
#'
#' synth_table(syn)


synth=function(fm,df,splines,pc_num,
                   nSim=1000,weights=NULL,max_clus=6,
                   Parallel=TRUE,exact_cholesky=TRUE,k_medoids=TRUE,xy_interaction=FALSE,avc=NULL){
#
  withr::local_preserve_seed()  #fixed simulation seeds do not change the user's random numbers
  if(!is.null(avc)) avc=check_avc(avc)
  prep=prepare_spatial_data(fm,df,splines,pc_num,weights,max_clus)
  df=prep$df
  rhs=prep$rhs
  pc=prep$pc
  rm(prep)


# Define two equations: the estimated equation using the true outcome variable and
# the simulated equation that uses paramaterized noise instead.
# Both equations have a spatial basis of principal components added.
eqs=build_formulas(rhs,pc,sim_replaces="dep_var")
eq_est=eqs$eq_est
eq_sim=eqs$eq_sim
rm(eqs)

# Regress dep_var on quadratic in long and lat to generate syn outcomes.
lm_res=synth_trend(df,xy_interaction)
rm(pc)

# Get spatial correlation pattern of residuals and generate synthetic noise with the same structure.
noise_sim=Noise_Sim(df,lm_res,nSim,exact_cholesky,Parallel)

#Moran test using 5 nearest neighbours
Moran=moran(eq_est,df)

#Spatial output
Spatial_Params=data.frame(Moran,R2=summary(lm_res)$r.squared,   #explanatory power of quadratic for y
                          Effective_Range=noise_sim$matern_params$Effective_Range,   #fraction of 95th perc distance bw coords
                          Structure=noise_sim$matern_params$Structure)
Spatial_Params=round(Spatial_Params,3)
Spatial_Params=cbind.data.frame(Spatial_Params,N=nrow(df),Splines=splines,PCs=pc_num)

#Simulated variables
Sim=noise_sim$Sim
rm(noise_sim)

# k-medoids clusters from 3 up to max_clus
hold_clus=sim_clusters(df,k_medoids,max_clus)

# SCPC spatial weights for each avc, which depend only on the locations.
spcs=if(is.null(avc)) NULL else scpc_setup(df,avc)

# p values of the treatment in regressions on synthetic outcomes with HC, BCH, IM and SCPC inference.
sim_out=ols_sim_p_values(df,Sim,eq_sim,hold_clus,nSim,Parallel,avc,spcs)

# Summary synth results
Results=ols_summary(df,eq_est,hold_clus,sim_out,avc,spcs)
Results=Results  |>
  dplyr::select(-sim_05)|>
  dplyr::rename(`Synth p`= sim_p,
                `Est p`=est_p,`CI Width`=width_ci)

obj=list(
  Results=Results,
  Spatial_Params=Spatial_Params

)
return(obj)

}
